class Inventory:
    def __init__(self):
        self.items = {}

    def add(self, name, qty):
        if name in self.items:
            self.items[name] = self.items[name] + qty
        else:
            self.items[name] = qty

    def count(self, name):
        if name in self.items:
            return self.items[name]
        else:
            return 0

    def remove(self, name, qty):
        if qty > self.count(name):
            raise ValueError("insufficient stock")
        self.items[name] -= qty
